import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"12 | 从任务分配角度来看管理","description":"","frontmatter":{},"headers":[{"level":2,"title":"如何合理地分配任务？","slug":"如何合理地分配任务","link":"#如何合理地分配任务","children":[{"level":3,"title":"选人","slug":"选人","link":"#选人","children":[]},{"level":3,"title":"任事","slug":"任事","link":"#任事","children":[]}]},{"level":2,"title":"信任其人，关注其事","slug":"信任其人-关注其事","link":"#信任其人-关注其事","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[{"level":3,"title":"任务分配表格示例","slug":"任务分配表格示例","link":"#任务分配表格示例","children":[]}]}],"relativePath":"技术领导力实战笔记2022/12｜从任务分配角度来看管理.md","filePath":"技术领导力实战笔记2022/12｜从任务分配角度来看管理.md","lastUpdated":1795558086000}'),l={name:"技术领导力实战笔记2022/12｜从任务分配角度来看管理.md"};function r(s,e,E,p,o,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_12-从任务分配角度来看管理" tabindex="-1">12 | 从任务分配角度来看管理 <a class="header-anchor" href="#_12-从任务分配角度来看管理" aria-label="Permalink to &quot;12 | 从任务分配角度来看管理&quot;">​</a></h1><p>你好，我是得物 App 交易平台 / 中间件平台 Team Leader Alan。今天我想跟你聊一聊我在技术管理中获益最大的一项能力，也是优秀的技术管理者必须具备的一项能力——合理分配任务的能力。</p><p>学会给团队中的成员分配适当、适量的工作任务，保证合适的人在合适的位置，不至于埋没人才，也不至于任务无人认领。任务分配得合理不仅能发挥团队中每个人的价值，还能从整体上提高团队的工作效率、形成良好的团队氛围。</p><h2 id="如何合理地分配任务" tabindex="-1">如何合理地分配任务？ <a class="header-anchor" href="#如何合理地分配任务" aria-label="Permalink to &quot;如何合理地分配任务？&quot;">​</a></h2><p>合理地分配任务，主要可以分为两个维度：选人和任事。换句话说就是挑选合适人去做合适的工作。我们先来看第一个维度，如何挑选合适的人？</p><h3 id="选人" tabindex="-1">选人 <a class="header-anchor" href="#选人" aria-label="Permalink to &quot;选人&quot;">​</a></h3><p>在选人层面应该先考虑成员的技术能力和业务熟悉程度。对于一项工作，最重要的还是拿到结果，如果预判到某些同学的历史积累、技术能力有助于拿到更好的结果，那么他就是最直接的人选。其次，团队成员的积极性及想要证明自己的迫切程度也是核心要素，也就是常说的：意愿和能力同等重要。</p><p>除此之外，选人时我还比较关注对方的性格，尤其是一些关键人选，比如一些情绪波动比较大，不擅长沟通的成员，被安排成项目负责人的几率会小一些，因为作为项目负责人非常重要的一项能力就是沟通能力，这一点做不好，很容易影响任务的进度。</p><p>另外，我们还可以考虑给部分同学更多机会，交给他们一些有挑战性的工作。比如团队里的新人、骨干及核心成员等。</p><ul><li><p>新人 Landing：团队里的新人，一般特指 level 较高的新人，比如架构师、小组 TL，让新人承担 Owner 的重要角色，同时搭配对工作内容比较熟悉的老员工，一方面可以考察新人的能力，另一方面新人在承担压力的同时也能快速熟悉业务、上下游团队同学，最后即使发挥欠佳，也随时有识途的老马可以快速顶上，避免造成比较大的损失。</p></li><li><p>给机会：很多时候团队里的同学并不是能力欠佳，而是缺乏证明自己的机会，给他们提供发挥能力的机会，进一步证明自己，积累成功的经验及影响力，对培养团队骨干来说非常关键。</p></li><li><p>内部培养：团队想要发展壮大，核心人员不能只依靠招聘外部成熟的角色，也需要团队内部培养。给核心人员倾斜更多资源及压力，在技能、协调能力、推动能力等多方面给予成长的机会，帮助他们成长，承担更重要的任务和角色。</p></li></ul><p>这些人是需要我们给予机会倾斜的。对于团队中一贯表现不达预期的同学，我们可以给 2～3次机会。从多方面考察他是不是因为不适应或不熟悉才无法正常发挥，还是面试能力大于实际工作能力；如果是前者，尽量帮他适应环境，找到合适的位置；如果是后者，就需要快速调整他的定位甚至汰换。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/1.png" alt=""></a></p><h3 id="任事" tabindex="-1">任事 <a class="header-anchor" href="#任事" aria-label="Permalink to &quot;任事&quot;">​</a></h3><p>知道了如何选人还不够，我们还要学会“任事”。</p><p>首先，我们可以根据已有的工作来安排，比如目前团队的工作主要来源于业务 &amp; 产品侧、技术改造、紧急的线上问题、效能提升等几个方面，如果同时在某个人身上堆积了太多工作，那么即使他能力很强，也会导致工作之间互相影响，所以任务一定要保持一个合适的量。</p><p>除了任务量，我们还需要考虑需求的紧迫性、时间周期、影响范围、跨团队协作情况等。</p><p>对于比较紧迫的工作，很多时候没得选，只能选择对工作最熟悉的人员；对于时间周期跨度比较长的事情，可以给新人负责，一方面可以有相对充足的时间去熟悉，另一方面如果过程中发现未达预期也可以有腾挪的空间；对于跨团队的需求，一般会考虑架构师、TL 或主导、或深度参与其中，确保方案合理、沟通顺畅。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/2.png" alt=""></a></p><h2 id="信任其人-关注其事" tabindex="-1">信任其人，关注其事 <a class="header-anchor" href="#信任其人-关注其事" aria-label="Permalink to &quot;信任其人，关注其事&quot;">​</a></h2><p>在工作分配后，我一般习惯于相信选择，深度授权，相信选择的人都有能力拿到好的结果。但同时，我们也要关注过程中的关键环节及内容，比如技术方案 Review、CR 情况、提测质量、性能指标、稳定性影响等，以便快速发现问题、协助对方解决问题。</p><p>如果不设置这些关键环节，又或者是设置了但你没有去关注，那么中间就很有可能出纰漏，我之前带过的项目就曾经出现过这样的问题。</p><p>2020 年恰逢大促前，团队有一个总人日超过 650、涉及上下游 4 个大团队的项目启动，当时指定的负责人 A，技术能力和经验都没问题，前期各方面也都比较顺畅。刚好我忙于准备大促，对项目的关注就少了一些。在项目进行到中后段的时候，他突然找到我说项目他不想继续做了。我在跟核心项目成员沟通之后，发现 A 在沟通方面存在一些问题，比如对持不同意见的同学缺乏耐心、情绪波动较大。各种小矛盾累积到后面，项目已经到了很难推进、质量也难以把控的程度。</p><p>当时与项目 PMO、各个团队的项目干系人讨论后，我决定亲自介入项目，组织大家充分讨论落地细节中不同的意见，疏通各个团队成员之间的关系；同时把 A 定位为项目主架构师，稳定他的情绪并肯定之前他做的工作，然后明确告诉他有些地方其实有更好的处理方式。</p><p>最终项目如期上线，不过这件事儿也让我记忆深刻，对后续我任务分配、工作推进的方式有很大影响，吸取这次的教训，我之后在项目实施过程中设置了多个中间节点关注项目进度、项目人员情况、项目质量，而不是仅仅依靠授权及信任。</p><p>同时，作为团队的管理者，我们要培养成员的“闭环思维”，凡事有交代、件件有着落、事事有回音。鼓励被分配到工作的同学积极反馈、主动沟通，在充分锻炼自己、证明自己、成长的同时，拿到一个好的结果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/3.png" alt=""></a></p><p>任务分配可以在事务方面充分体现一个 TL 的管理能力，不管是识人、任事，还是冲突管理、压力管理等等，各方面都可以在其中展示出来。如果过程中发现出现各种意外，或者结果并未达预期，不要怀疑，对，就是你的主要责任，这时候就要反思你对团队支撑的业务现状、团队成员，至少是骨干成员的能力，是否了解得不够透彻，接下来该如何修正、改进。</p><p>同时，这个过程也是不断地磨合团队、搭建梯队的过程，我团队内部把“任务分配”叫做 Owner机制，每个需求、项目都会确定 Owner 人选，也会持续跟踪关注 Owner 在过程中的表现，甚至会要求 Owner 做技术复盘、参与业务复盘。</p><p>这套机制一方面可以确保每个任务都有人负责，球不会掉在地上；另一方面基本上每个人都有机会充分发挥；团队中的骨干、甚至小 TL 大都会从中凸显出来，团队也慢慢形成了TL/PM/Owner 多级人才梯队，backup 机制也会随之形成。借事修人修己，在这个过程中自己与团队共同成长，获益良多。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>团队中新加入了几名成员，你会分配什么样的任务给他们呢？欢迎你在评论区留下你的见解和我一起讨论，也欢迎你把这节课分享给需要的朋友。</p><h3 id="任务分配表格示例" tabindex="-1">任务分配表格示例 <a class="header-anchor" href="#任务分配表格示例" aria-label="Permalink to &quot;任务分配表格示例&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/12/4.png" alt=""></a></p>',34)])])}const u=t(l,[["render",r]]);export{c as __pageData,u as default};
